entries[12846] = { ["name"] = "Meisterschaft: Entzünden", ["text"] = "Euer Ziel erleidet im Verlauf von 9 Sek. zusätzlichen Feuerschaden in Höhe von 4.0% des gesamten direkten Schadens, den Ihr mit Euren Zaubern 'Feuerball', 'Feuerschlag', 'Versengen', 'Pyroschlag' [ Meteor : 'Meteor' ] [ Phönixflammen : 'Phönixflammen' ] [ Funkensturm : 'Funkensturm' ] und 'Flammenstoß' verursacht. Wenn dieser Effekt erneut angewendet wird, wird der verbleibende Schaden dem neuen Effekt von 'Entzünden' hinzugefügt.\n\n'Feuerschlag' bewirkt, dass Euer Effekt 'Entzünden' sich auf 3 Gegner in der Nähe ausbreitet." }
entries[12851] = { ["name"] = "Die Hunde loslassen", ["text"] = "Wirken in 2 sek.\nBeschwört einen Teufelshundfährtenleser. Lest das Handbuch!" }
