entries[12895] = { ["name"] = "Pläne: Veredelter Mithrilzylinder", ["text"] = "Wirken in 3.5 sek.\nReagenzien:\nLeichtes Pergament , Ingenieurstinte\nBerufsausbilder:\nKlassische Ingenieurskunst (205)\nKosten:\n4\n10\n\nBenutzen: Lehrt Euch die Herstellung eines veredelten Mithrilzylinders. Dieser Gegenstand wird von Gnomeningenieuren verwendet.\nBenötigt Klassische Schmiedekunst\n(200)" }
