entries[12897] = { ["name"] = "Gnomenschutzbrille", ["text"] = "Wirken in 2 sek.\nTools: Bogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nFeuerschutzbrille , Mithrilrohr , Goldkraftkern (2), Schweres Leder (2)\nOptionale Reagenzien:\n[] (#31)\nBerufsausbilder:\nKlassische Ingenieurskunst (215)\nKosten:\n5\n25\n\nGnomenschutzbrille\nWird beim Aufheben gebunden\nKopf Stoff\n3 Rüstung\n+3 Intelligenz\n+5 Ausdauer\n+ 5 Vielseitigkeit\nHaltbarkeit 70 / 70\nBenötigt Klassische Ingenieurskunst\n(1)" }
