entries[12899] = { ["name"] = "Gnomenschrumpfstrahl", ["text"] = "Wirken in 2 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nMithrilrohr , Instabiler Auslöser , Mithrilbarren (4), Jade (2)\nBerufsausbilder:\nKlassische Ingenieurskunst (205)\nKosten:\n4\n10\n\nGnomenschrumpfstrahl\nWird beim Anlegen gebunden\nSchmuck\nBenutzen: Lässt das Ziel schrumpfen und verringert seine Angriffskraft um 31 . Zumindest ist das meistens der Fall... (5 Min Abklingzeit)\nBenötigt Klassische Ingenieurskunst\n(205)" }
entries[12900] = { ["name"] = "Mobiler Alarm", ["text"] = "Wirken in 2 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nMithrilrohr , Instabiler Auslöser , Mithrilbarren (4)" }
entries[12902] = { ["name"] = "Gnomen-Net-o-Matik-Projektor", ["text"] = "Wirken in 2 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nMithrilrohr , Schattenseide (2), Dicke Spinnenseide (4), Robustes Sprengpulver (2), Mithrilbarren (4)\nBerufsausbilder:\nKlassische Ingenieurskunst (210)\nKosten:\n4\n60\n\nGnomen-Net-o-Matik-Projektor\nWird beim Anlegen gebunden\nSchmuck\nBenutzen: Hält das Ziel 20 Sek. lang in einem Netz fest. Das Netz ist allerdings mit einer Menge Haken bestückt und verfängt sich manchmal auch in der Kleidung des Benutzers, wenn es abgefeuert wird... (10 Min Abklingzeit)\nBenötigt Klassische Ingenieurskunst\n(210)" }
entries[12903] = { ["name"] = "Gnomenunglücksverhinderungsgürtel", ["text"] = "Wirken in 2 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nSchwärzlicher Gürtel , Mithrilbarren (4), Echtsilberbarren (2), Instabiler Auslöser , Aquamarin (2)\nOptionale Reagenzien:\n[] (#31)\nBerufsausbilder:\nKlassische Ingenieurskunst (215)\nKosten:\n5\n25\n\nGnomenunglücksverhinderungsgürtel\nWird beim Anlegen gebunden\nTaille Leder\n3 Rüstung\n+3 Ausdauer\nHaltbarkeit 40 / 40\nBenutzen: Ein Kraftfeldschild schützt Euch 10 Min. lang vor bis zu 9 Schaden.\nWARNUNG: Kraftfeld kann überladen werden, wenn es getroffen wird. Der Träger wird dann für gewisse Zeit aus dieser Dimension entfernt. (Procchance: 5%) (1 Stunde Abklingzeit)\nBenötigt Klassische Ingenieurskunst\n(1)" }
entries[12905] = { ["name"] = "Gnomenraketenstiefel", ["text"] = "Wirken in 2 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nSchwarze Magiestoffstiefel , Mithrilrohr (2), Schweres Leder (4), Robustes Sprengpulver (8), Gyrochronatom (4)\nBerufsausbilder:\nKlassische Ingenieurskunst (210)\nKosten:\n4\n60\n\nGnomenraketenstiefel\nWird beim Anlegen gebunden\nFüße Stoff\n2 Rüstung\nHaltbarkeit 55 / 55\nBenutzen: Diese Stiefel erhöhen Eure Bewegungsgeschwindigkeit 20 Sek. lang erheblich. WARNUNG: Ihre Stromversorgung und Gyros funktionieren nicht immer so, wie sie eigentlich sollten. (15 Min Abklingzeit)\nBenötigt Klassische Ingenieurskunst\n(1)" }
entries[12906] = { ["name"] = "Gnomenkampfhuhn", ["text"] = "Wirken in 2 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nMithrilgehäuse , Echtsilberbarren (6), Mithrilbarren (6), Veredelter Mithrilzylinder (2), Goldkraftkern , Jade (2)\nBerufsausbilder:\nKlassische Ingenieurskunst (230)\nKosten:\n9\n\nWird beim Aufheben gebunden\nSchmuck\nBenutzen: Erschafft ein Kampfhuhn, das 1.5 Min. lang oder bis es zerstört wird für Euch kämpft. (20 Min Abklingzeit)\nBenötigt Klassische Ingenieurskunst\n(230)" }
entries[12907] = { ["name"] = "Gnomische Gedankenkontrollkappe", ["text"] = "Wirken in 2 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nMithrilbarren (10), Echtsilberbarren (4), Goldkraftkern , Sternrubin (2), Magiestoff (4)\nOptionale Reagenzien:\n[] (#31)\nBerufsausbilder:\nKlassische Ingenieurskunst (235)\nKosten:\n10\n50\n\nGnomische Gedankenkontrollkappe\nWird beim Anlegen gebunden\nKopf Stoff\n3 Rüstung\n+ 7 Vielseitigkeit\nHaltbarkeit 70 / 70\nBenötigt Klassische Ingenieurskunst\n(1)" }
entries[12908] = { ["name"] = "Goblindrachengewehr", ["text"] = "Wirken in 3 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nMithrilrohr (2), Goblinraketentreibstoff (4), Mithrilbarren (6), Echtsilberbarren (6), Instabiler Auslöser\nBerufsausbilder:\nKlassische Ingenieurskunst (240)\nKosten:\n13\n\nWird beim Aufheben gebunden\nSchmuck\nBenutzen: Fügt jedem Feind in einem kegelförmigen Bereich vor dem Ingenieur, der die Waffe benutzt, 10 Sek. lang 2 Feuerschaden zu. Es sei denn, sie explodiert... (5 Min Abklingzeit)" }
