entries[13729] = { ["name"] = "Flammenschock", ["text"] = "20 Meter Reichweite\nSofort\nVerbrennt sofort einen Feind und fügt ihm dann 12 Sek. lang alle 3 Sek. zusätzlichen Feuerschaden zu." }
