entries[13737] = { ["name"] = "Tödlicher Stoß", ["text"] = "Nahkampfreichweite\nWirken in 1 sek. 10 sek. Abklingzeit\nBenötigt Nahkampfwaffe\nVerursacht körperlichen Schaden und hinterlässt eine schwere Wunde, die die Effektivität eintreffender Heilung 5 Sek. lang um 25% verringert." }
