entries[13744] = { ["name"] = "Loderflammenemblem", ["text"] = "195 Mana 30 Meter Reichweite\nSofort\nErhöht Feuerwiderstand um 47 und verringert jeglichen Feuerschaden 15 Sek. lang um bis zu 24 ." }
entries[13745] = { ["name"] = "Arkane Explosion", ["text"] = "120 Mana\nWirken in 1.5 sek.\nLässt eine Druckwelle aus Magie entstehen und fügt in der Nähe befindlichen Feinden Arkanschaden zu." }
entries[13746] = { ["name"] = "Große Verteidigung", ["text"] = "Wirken in 2 sek.\nBenötigt Umhang\nTools: Runenverzierte Verzauberkunstrute\nReagenzien:\nSchwerer Illusionsstaub (2)\nBerufsausbilder:\nKlassische Verzauberkunst (205)\nKosten:\n4\n10" }
entries[13747] = { ["name"] = "Verlangsamen", ["text"] = "140 Mana 30 Meter Reichweite\nSofort 10 sek. Abklingzeit\nErhöht die Zeit zwischen Angriffen sowie die Zauberzeit von Gegnern in der Nähe um 50% und verringert ihre Bewegungsgeschwindigkeit um 60%. Hält 6 Sek. lang an." }
entries[13750] = { ["name"] = "Adrenalinrausch", ["text"] = "Sofort 3 min Abklingzeit\nErhöht 20 Sek. lang Eure Energieregenerationsrate um 50%, Eure maximale Energie um 50 und Euer Angriffstempo um 20%." }
entries[13752] = { ["name"] = "Feenfeuer", ["text"] = "55 Mana 30 Meter Reichweite\nSofort\nVerringert die Rüstung des Ziels 30 Sek. lang um 331 . Während der Wirkungsdauer kann das Ziel weder Verstohlenheit anwenden noch unsichtbar werden." }
entries[13787] = { ["name"] = "Dämonenrüstung", ["text"] = "Sofort 10 sek. Abklingzeit\nLässt den Zaubernden 25% weniger körperlichen Schaden und 15% weniger Schattenschaden erleiden und erhöht die Gesundheitsregeneration um 20%. Hält 30 Min. lang an." }
entries[13808] = { ["name"] = "M73 Schrapnellgranate", ["text"] = "30 Meter Reichweite\nSofort\nFügt Zielen in einem Umkreis von 10 Metern 11 Feuerschaden zu und macht sie 3 Sek. lang handlungsunfähig. Jeglicher Schaden wird den Effekt abbrechen." }
entries[13809] = { ["name"] = "Frostfalle", ["text"] = "Sofort 30 sek. Abklingzeit\nPlatziert eine Frostfalle, die 30 Sek. lang um sich herum eine Eisfläche bildet, sobald sich ihr der erste Gegner nähert. Die Bewegungsgeschwindigkeit aller Gegner in einem Umkreis von 10 Metern wird um 50% verringert, solange sie sich im Effektbereich befinden. Die Falle bleibt 1 Min. lang bestehen." }
entries[13810] = { ["name"] = "Frostfalle", ["text"] = "Unbegrenzte Reichweite\nSofort\nPlatziert eine Frostfalle, die 30 Sek. lang um sich herum eine Eisfläche bildet, sobald sich ihr der erste Gegner nähert. Die Bewegungsgeschwindigkeit aller Gegner in einem Umkreis von 10 Metern wird um 50% verringert, solange sie sich im Effektbereich befinden. Die Falle bleibt 1 Min. lang bestehen." }
entries[13812] = { ["name"] = "Sprengfalle", ["text"] = "100 Meter Reichweite\nSofort\nSchleudert eine Feuerfalle in den Zielbereich, die explodiert, wenn sich ein Gegner nähert. Die Falle verursacht (54.054% der Angriffskraft) Feuerschaden und fügt zusätzlich allen Gegnern innerhalb von 8 Metern im Verlauf von 10 Sek. (54.054% der Angriffskraft) Feuerschaden zu. Die Falle bleibt 1 Min. lang bestehen." }
