entries[15980] = { ["name"] = "Manabrand", ["text"] = "30 Meter Reichweite\nWirken in 3 sek.\nTrifft einen Feind mit einem Antimanablitz. Für jeden vom Blitz verbrauchten Manapunkt erleidet das Ziel 1 Schaden." }
entries[15981] = { ["name"] = "Verjüngung", ["text"] = "90 Mana 40 Meter Reichweite\nSofort\nHeilt einen Verbündeten 12 Sek. lang alle 3 Sek." }
entries[15982] = { ["name"] = "Welle der Heilung", ["text"] = "40 Meter Reichweite\nWirken in 3 sek.\nRuft Naturmagie an, um einen Verbündeten zu heilen." }
entries[15993] = { ["name"] = "Bijou-Entschwinden" }
entries[15998] = { ["name"] = "Worgwelpen einfangen", ["text"] = "5 Meter Reichweite\nWirken in 2.5 sek.\nIn der Nähe eines Worgwelpen der Blutäxte verwenden. Keine Sorge, ist vom Fantasy-Tierschutz genehmigt." }
entries[15999] = { ["name"] = "Worgwelpe", ["text"] = "Sofort\nMit Rechtsklick Euren Worgwelpen beschwören oder wieder freigeben." }
entries[16000] = { ["name"] = "Werfen", ["text"] = "5 - 30 Meter Reichweite\nSofort\nWirft eine Waffe auf einen Gegner und fügt ihm körperlichen Schaden zu." }
entries[16001] = { ["name"] = "Durchbohren", ["text"] = "5 - 30 Meter Reichweite\nSofort\nFügt einem Feind 9 Sek. lang alle 3 Sek. körperlichen Schaden zu." }
entries[16002] = { ["name"] = "Brennenden Teufelshund beschwören", ["text"] = "Sofort\nBeschwört für 10 Min. einen brennenden Teufelshund." }
entries[16003] = { ["name"] = "Feuerbrand - Bild - Passiv" }
entries[16004] = { ["name"] = "Brennende Teufelswache beschwören" }
entries[16005] = { ["name"] = "Feuerregen", ["text"] = "30 Meter Reichweite\nKanalisiert (Wirken in 9 sek.)\nLässt einen Schmelzregen niedergehen, der alle Feinde in einem ausgewählten Gebiet verbrennt und ihnen 9 Sek. lang alle 3 Sek. 183 Feuerschaden zufügt." }
entries[16006] = { ["name"] = "Kettenblitzschlag", ["text"] = "30 Meter Reichweite\nWirken in 3 sek.\nTrifft einen Feind mit einem Blitzschlag, der auf einen in der Nähe befindlichen Feind überspringt. Der Zauber wirkt sich auf bis zu 3 Ziele aus und fügt jedem Naturschaden zu." }
entries[16007] = { ["name"] = "Draco-Incarcinatrix 900", ["text"] = "10 Meter Reichweite\nWirken in 2 sek.\nAuf einen Drachkinbrutling in der Brennenden Steppe feuern." }
entries[16027] = { ["name"] = "Brutlingessenz herstellen" }
entries[16028] = { ["name"] = "Brutstättenei einfrieren - Prototyp", ["text"] = "10 Meter Reichweite\nWirken in 0.5 sek.\nAuf ein Brutstättenei anwenden und dann zu Tinkee zurückkehren." }
entries[16029] = { ["name"] = "Eiszillioskop herstellen", ["text"] = "Unbegrenzte Reichweite\nSofort\nReagenzien:\nGelbe Lochkarte" }
entries[16031] = { ["name"] = "Verderbten Schlamm freigeben", ["text"] = "30 Meter Reichweite\nWirken in 5 sek.\nGibt gefangenen Teufelswaldschlamm frei, sodass er mit einem Urzeitschlamm aus dem Krater von Un'Goro interagieren kann." }
entries[16032] = { ["name"] = "Verschmelzende Schlamme", ["text"] = "5 Meter Reichweite\nWirken in 0.5 sek.\nEin gefangener Schlamm aus dem Teufelswald verschmilzt mit einem Urzeitschlamm aus dem Kraters von Un'Goro." }
entries[16033] = { ["name"] = "Kettenblitzschlag", ["text"] = "150 Mana 30 Meter Reichweite\nWirken in 3 sek. 6 sek. Abklingzeit\nTrifft einen Feind mit einem Blitzschlag, der auf einen in der Nähe befindlichen Feind überspringt. Der Zauber wirkt sich auf bis zu 10 Ziele aus und fügt jedem folgenden Ziel immer größeren Naturschaden zu." }
entries[16034] = { ["name"] = "Schock", ["text"] = "135 Mana 20 Meter Reichweite\nSofort 6 sek. Abklingzeit\nSchleudert sofort einen Blitz auf einen Feind und verursacht Naturschaden." }
entries[16037] = { ["name"] = "Gedankenerforschung" }
entries[16044] = { ["name"] = "Spalten", ["text"] = "Nahkampfreichweite\nNächster Nahkampf\nBenötigt Nahkampfwaffe\nFügt einem Gegner und seinen nächsten Verbündeten Waffenschaden plus 125 zu, wirkt auf bis zu 10 Ziele." }
entries[16045] = { ["name"] = "Einsperren", ["text"] = "30 Meter Reichweite\nKanalisiert (Wirken in 10 sek.)\nSperrt einen Feind ein und betäubt ihn 10 Sek. lang." }
entries[16046] = { ["name"] = "Druckwelle", ["text"] = "Sofort\nEntfesselt eine Flammenwelle, die Feuerschaden bei in der Nähe befindlichen Feinden verursacht und ihre Bewegungsgeschwindigkeit 6 Sek. lang verringert." }
entries[16047] = { ["name"] = "Glutseher - volle Kraft" }
entries[16048] = { ["name"] = "Glutseher - wachsend" }
entries[16049] = { ["name"] = "Glutseher - wachsend" }
entries[16050] = { ["name"] = "Verlangsamender Schlamm", ["text"] = "Nahkampfreichweite\nSofort 10 sek. Abklingzeit\nErhöht die Zeit zwischen Angriffen eines Gegners um 25% und verlangsamt seine Bewegungsgeschwindigkeit um 80%. Hält 10 Sek. lang an." }
entries[16051] = { ["name"] = "Lichtbarriere" }
entries[16052] = { ["name"] = "Glutseher transformieren" }
entries[16053] = { ["name"] = "Herrschaft der Seele", ["text"] = "20 Meter Reichweite\nWirken in 3 sek.\nKontrolliert Aschenschwinges Gedanken, wenn sein Wille schwindet." }
entries[16054] = { ["name"] = "Flammen des schwarzen Drachenschwarms" }
entries[16055] = { ["name"] = "Schwarzer Nachtsäbler", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen reitbaren schwarzen Nachtsäbler oder gibt ihn wieder frei.\n\"Diese gewandten Bestien gehören zu den perfektesten Raubtieren in Azeroth und können durch dichte Wälder sprinten, ohne ein Geräusch zu verursachen.\"\nKlassisch" }
entries[16056] = { ["name"] = "Uralter Frostsäbler", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen reitbaren uralten Frostsäbler oder gibt ihn wieder frei.\n\"Am Fehlen von Flecken oder Streifen kann man klar erkennen, dass dies der Nachfahre einer der ältesten Frostsäblerfamilien ist.\"\nKlassisch" }
entries[16057] = { ["name"] = "Ungeschmiedetes Siegel platzieren", ["text"] = "5 Meter Reichweite\nWirken in 0.5 sek.\nPlatziert das ungeschmiedete Siegel des Aufstiegs. Vor Aschenschwinge benutzen." }
entries[16058] = { ["name"] = "Urleopard", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen reitbaren Urzeitleoparden oder gibt ihn wieder frei." }
entries[16059] = { ["name"] = "Lohfarbene Säblerkatze", ["text"] = "Wirken in 1.5 sek.\nBeschwört eine reitbare lohfarbene Säblerkatze oder gibt sie wieder frei." }
entries[16060] = { ["name"] = "Goldfarbene Säblerkatze", ["text"] = "Wirken in 1.5 sek.\nBeschwört eine reitbare goldene Säblerkatze oder gibt sie wieder frei." }
entries[16068] = { ["name"] = "Einsperren" }
entries[16069] = { ["name"] = "Ruchloser Angriff 001" }
entries[16070] = { ["name"] = "Ruchloser Angriff 000", ["text"] = "60 Meter Reichweite\nSofort\nSchleudert ein arkanes Geschoss auf den Feind und verursacht 1 Arkanschaden." }
entries[16071] = { ["name"] = "Fluch der Feuerbrand", ["text"] = "30 Meter Reichweite\nWirken in 2 sek.\nFügt 30 Sek. lang einem Feind alle 6 Sek. 50 Feuerschaden zu." }
entries[16072] = { ["name"] = "Essen läutern und platzieren", ["text"] = "Nahkampfreichweite\nWirken in 5 sek.\nReagenzien:\nObstprobe der Schwarzfelle , Getreideprobe der Schwarzfelle , Nussprobe der Schwarzfelle\nLässt eine Schale geläuterten Essens entstehen, das die Furbolgs bestimmt gern mögen. Dafür werden Früchte, Getreide und Nüsse vom Lager der Schwarzfelle benötigt." }
entries[16073] = { ["name"] = "Füllen", ["text"] = "5 Meter Reichweite\nWirken in 3 sek.\nFüllt die Schale mit Mondbrunnenwasser, um das Essen in ihr zu säubern." }
entries[16074] = { ["name"] = "Brennende Teufelswache - Spawn" }
entries[16075] = { ["name"] = "Axt werfen", ["text"] = "40 Meter Reichweite\nWirken in 1 sek.\nSchleudert eine massive Axt auf einen zufälligen Gegner, verursacht 1158 Schaden und betäubt ihn 2 Sek. lang." }
entries[16077] = { ["name"] = "Füllen", ["text"] = "10 Meter Reichweite\nWirken in 4 sek.\nNimmt eine Probe vom Klippenquell." }
entries[16078] = { ["name"] = "Glutseher - Despawn" }
entries[16079] = { ["name"] = "Feuernova", ["text"] = "Sofort\nFügt Gegnern in der Nähe Feuerschaden zu." }
entries[16080] = { ["name"] = "Roter Wolf", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen reitbaren roten Wolf oder gibt ihn wieder frei.\n\"Es verbleiben nur noch wenige in ganz Azeroth, und nur die Erfahrensten von uns haben sie je zu Gesicht bekommen.\"\nKlassisch" }
entries[16081] = { ["name"] = "Arktischer Wolf", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen reitbaren arktischen Wolf oder gibt ihn wieder frei.\n\"Einst dachte man, sie wären beinahe ausgestorben, doch können diese Wölfe gelegentlich in der Begleitung von einigen Hordenveteranen gesehen werden.\"\nKlassisch" }
entries[16082] = { ["name"] = "Palomino", ["text"] = "Wirken in 1.5 sek.\nBeschwört ein reitbares Palomino oder gibt es wieder frei.\n\"Der menschliche Adel hat diese majestätische Spezies wegen des wunderschönen goldenen Fells und der wallenden weißen Mähne schon lange bevorzugt.\"\nKlassisch" }
